sp_widget.client_script:
api.controller = function(spModal, spUtil) {
  var c = this;

  c.tab = 'overview';

  c.form = {
    score:    c.data.score      || '',
    comments: c.data.work_notes || ''
  };

  c.newNote    = '';
  c.saving     = false;
  c.addingNote = false;
  c.rejecting  = false;
  c.error      = '';

  // ── VISIBILITY FLAGS ──
  c.isCompleted = (c.data.status === 'Review completed');
  c.canScore    = !c.isCompleted && c.data.is_last_reviewer;
  c.isReadOnly  = !c.isCompleted && !c.data.is_last_reviewer && !c.data.submitted;

  // ── FORMAT FILE SIZE ──
  c.formatSize = function(bytes) {
    if (!bytes) return '';
    return (parseInt(bytes) / 1024).toFixed(2) + ' KB';
  };

  // ── SUBMIT / PROCEED ──
  c.submit = function() {
    if (!c.data.found) {
      c.error = 'No record found.';
      return;
    }

    if (c.canScore && !c.form.score) {
      c.error = 'Please select a score before submitting.';
      return;
    }

    c.saving = true;
    c.error  = '';

    c.data.action = 'submit_review';
    c.data.form   = angular.copy(c.form);

    c.server.update().then(function() {
      c.saving = false;

      if (c.data.success) {
        var msg = c.data.last_reviewer
          ? 'Review completed! All groups have finished reviewing.'
          : 'Review submitted! Assigned to next group: ' + (c.data.next_group || '');

        spModal.alert(msg).then(function() {
          spUtil.navigate('review');
        });
      } else {
        c.error = c.data.error || 'An unexpected server error occurred.';
      }
    });
  };

  // ── ADD WORK NOTE ──
  c.addNote = function() {
    if (!c.newNote || !c.newNote.trim()) return;

    c.addingNote = true;
    c.error      = '';

    c.data.action = 'add_note';
    c.data.form   = { comments: c.newNote };

    c.server.update().then(function() {
      c.addingNote = false;

      if (c.data.success) {
        c.newNote = '';
        spModal.alert('Work note added successfully!');
      } else {
        c.error = c.data.error || 'Failed to add note.';
      }
    });
  };

  // ── REJECT REVIEW ──
  c.rejectReview = function() {
    spModal.confirm('Are you sure you want to decline this review? This cannot be undone.')
      .then(function(confirmed) {
        if (!confirmed) return;

        c.rejecting   = true;
        c.error       = '';
        c.data.action = 'reject_review';

        c.server.update().then(function() {
          c.rejecting = false;

          if (c.data.success) {
            c.data.status = 'Declined by Reviewer';
            c.isCompleted = true;
            c.canScore    = false;
            c.isReadOnly  = false;

            spModal.alert('Review declined successfully.').then(function() {
              spUtil.navigate('review');
            });
          } else {
            c.error = c.data.error || 'Failed to decline the review.';
          }
        });
      });
  };

};

sp_widget.css:
/* ═══════ RESET ═══════ */
.rp-shell *, .rp-denied * { box-sizing: border-box; }
.rp-shell {
  max-width: 100%;
margin: 0;                /* ← remove auto centering */
  padding: 0 0 80px; 
  font-family: 'Inter', 'Segoe UI', system-ui, sans-serif;
  font-size: 13.5px;
  color: #1a1d23;
  background: #f4f5f7;
  min-height: 100vh;
}

/* ═══════ DENIED ═══════ */
.rp-denied {
  display: flex; justify-content: center; align-items: center;
  min-height: 60vh;
}
.rp-denied__box {
  text-align: center; max-width: 380px;
  background: #fff; border-radius: 20px; padding: 48px 32px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.08);
}
.rp-denied__ico {
  width: 72px; height: 72px; border-radius: 50%;
  background: #fef2f2; display: flex; align-items: center;
  justify-content: center; font-size: 26px; color: #ef4444;
  margin: 0 auto 16px;
}
.rp-denied h3 { font-size: 18px; font-weight: 700; margin: 0 0 8px; }
.rp-denied p  { color: #6b7280; font-size: 13px; margin: 0 0 20px; }

/* ═══════ HERO ═══════ */
.rp-hero {
  background: #fff;
 border-radius: 0;           /* ← was 0 0 20px 20px, flatten for full width */
  padding: 20px 28px 24px;   /* ← consistent inner padding */
  margin:  54px 0 16px; 
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  flex-wrap: wrap;
}
.rp-breadcrumb {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 11.5px; font-weight: 600; color: #9ca3af;
  text-decoration: none; margin-bottom: 8px;
  transition: color .15s;
}
.rp-breadcrumb:hover { color: #6366f1; }
.rp-breadcrumb__sep { font-size: 9px; opacity: 0.5; }
.rp-hero__title-row {
  display: flex; align-items: center; gap: 10px;
  flex-wrap: wrap; margin-bottom: 8px;
}
.rp-hero__title {
  font-size: 22px; font-weight: 800; color: #111827; margin: 0;
}
.rp-hero__meta {
  display: flex; align-items: center; gap: 8px;
  font-size: 12.5px; color: #6b7280; flex-wrap: wrap;
}
.rp-hero__meta-item {
  display: flex; align-items: center; gap: 5px; font-weight: 500;
}
.rp-hero__meta-item i { color: #c4c9d4; }
.rp-hero__meta-sep { color: #d1d5db; }

.rp-hero__score { text-align: center; }
.rp-hero__score-ring {
  width: 72px; height: 72px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  flex-direction: column;
  border: 3px solid transparent;
  margin: 0 auto 6px;
}
.rp-ring--green { background: #d1fae5; border-color: #10b981; }
.rp-ring--amber { background: #fef3c7; border-color: #f59e0b; }
.rp-ring--red   { background: #fee2e2; border-color: #ef4444; }
.rp-ring--empty { background: #f3f4f6; border-color: #e5e7eb; }
.rp-hero__score-num { font-size: 22px; font-weight: 900; color: #111827; line-height: 1; }
.rp-hero__score-num--dash { font-size: 20px; color: #9ca3af; }
.rp-hero__score-den { font-size: 11px; color: #9ca3af; font-weight: 600; }
.rp-hero__score-label { font-size: 11px; font-weight: 600; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; }

/* ═══════ STATUS PILLS ═══════ */
.rp-status-dot {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11.5px; font-weight: 700;
  padding: 4px 10px 4px 7px; border-radius: 999px;
}
.rp-dot__pulse {
  width: 8px; height: 8px; border-radius: 50%;
  background: currentColor; opacity: .7;
  animation: rpPulse 2s infinite;
}
@keyframes rpPulse {
  0%,100% { transform: scale(1); opacity:.7; }
  50%      { transform: scale(1.3); opacity:1; }
}
.rp-dot--green { background: #d1fae5; color: #059669; }
.rp-dot--blue  { background: #dbeafe; color: #1d4ed8; }
.rp-dot--amber { background: #fef3c7; color: #d97706; }
.rp-dot--red   { background: #fee2e2; color: #dc2626; }
.rp-dot--empty { background: #f3f4f6; color: #9ca3af; }

.rp-locked-chip {
  background: #fef3c7; color: #92400e;
  font-size: 11.5px; font-weight: 700;
  padding: 3px 10px; border-radius: 999px;
  display: inline-flex; align-items: center; gap: 4px;
  border: 1px solid #fde68a;
}

/* ═══════ BANNER ═══════ */
.rp-banner {
  background: #ecfdf5; border: 1px solid #a7f3d0; color: #065f46;
  padding: 10px 28px;        /* ← match side padding */
  border-radius: 0;          /* ← flat */
  margin-bottom: 0;
  display: flex; align-items: center; gap: 10px;
  font-size: 13px; font-weight: 500;
}
.rp-banner i { font-size: 16px; flex-shrink: 0; }

/* ═══════ TABS ═══════ */
.rp-tabs {
  display: flex; gap: 2px;
  background: #fff;
  border-radius: 0;           /* ← flat to match full width */
  padding: 5px 28px;         /* ← horizontal padding instead of margin */
  margin-bottom: 16px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.06);
  overflow-x: auto;
  scrollbar-width: none;
}

.rp-tabs::-webkit-scrollbar { display: none; }

.rp-tab {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 9px 16px;
  border-radius: 10px;
  font-size: 13px; font-weight: 600;
  color: #6b7280;
  background: transparent;
  border: none;
  cursor: pointer;
  white-space: nowrap;
  transition: all .18s;
  position: relative;
}
.rp-tab:hover { background: #f9fafb; color: #374151; }
.rp-tab--active {
  background: #6366f1;
  color: #fff;
  box-shadow: 0 3px 10px rgba(99,102,241,.3);
}
.rp-tab--active:hover { background: #4f46e5; }

.rp-tab__badge {
  background: rgba(255,255,255,0.25);
  color: #fff;
  font-size: 10.5px;
  font-weight: 800;
  padding: 1px 7px;
  border-radius: 999px;
  line-height: 1.6;
}
.rp-tab:not(.rp-tab--active) .rp-tab__badge {
  background: #e0e7ff;
  color: #4338ca;
}

/* ═══════ TAB PANEL ═══════ */
.rp-tab-panel { animation: rpFadeIn .2s ease;  padding: 0 28px;  }
@keyframes rpFadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ═══════ LAYOUTS ═══════ */
.rp-ov-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 16px;
  align-items: start;
}
.rp-twoCol {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  align-items: start;
}
.rp-review-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  align-items: start;
}

/* ═══════ CARD ═══════ */
.rp-card {
  background: #fff;
  border-radius: 16px;
  border: 1px solid #e9eaec;
  margin-bottom: 14px;
  overflow: hidden;
  transition: box-shadow .2s;
}
.rp-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.07); }
.rp-card--sticky { position: sticky; top: 16px; }

.rp-card__head {
  display: flex; align-items: center; gap: 10px;
  padding: 13px 16px;
  background: #fafbfc;
  border-bottom: 1px solid #f0f1f3;
}
.rp-card__head-icon {
  width: 32px; height: 32px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; flex-shrink: 0;
}
.rp-ci--indigo { background: #e0e7ff; color: #4338ca; }
.rp-ci--violet { background: #ede9fe; color: #7c3aed; }
.rp-ci--teal   { background: #d1fae5; color: #059669; }
.rp-ci--amber  { background: #fef3c7; color: #d97706; }
.rp-ci--slate  { background: #f1f5f9; color: #64748b; }

.rp-card__head-title {
  font-size: 13.5px; font-weight: 700; color: #111827;
}
.rp-card__body {
  padding: 14px 16px;
}
.rp-card__body--center { text-align: center; }

/* ═══════ FIELD GRID ═══════ */
.rp-fields { display: grid; gap: 12px 14px; }
.rp-fields--2 { grid-template-columns: 1fr 1fr; }
.rp-fields--3 { grid-template-columns: 1fr 1fr 1fr; }
.rp-f { display: flex; flex-direction: column; gap: 3px; }
.rp-f--span2 { grid-column: 1 / -1; }

.rp-f__l {
  font-size: 10px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .6px;
  color: #b0b7c3;
}
.rp-f__v {
  font-size: 13.5px; color: #374151; font-weight: 500;
}
.rp-f__v i { color: #c4c9d4; margin-right: 3px; font-size: 11px; }
.rp-f__v--bold  { font-weight: 700; color: #111827; }
.rp-f__v--lg    { font-size: 15px; }
.rp-f__v--money { font-weight: 700; color: #059669; }

.rp-link {
  color: #6366f1; text-decoration: none; font-size: 13px; font-weight: 500;
}
.rp-link:hover { color: #4338ca; text-decoration: underline; }

.rp-secure {
  display: inline-flex; align-items: center; gap: 5px;
  font-family: 'Courier New', monospace; font-size: 12px;
  color: #6b7280; background: #f9fafb;
  padding: 3px 8px; border-radius: 6px;
  border: 1px solid #f0f1f3;
}

.rp-mono-chip {
  background: #f3f4f6; color: #374151;
  font-size: 11.5px; font-weight: 700; font-family: monospace;
  padding: 2px 9px; border-radius: 6px;
}
.rp-mono-chip--sm { font-size: 11px; }

.rp-badge {
  display: inline-block; padding: 3px 9px;
  border-radius: 6px; font-size: 11.5px; font-weight: 700;
  width: fit-content;
}
.rp-badge--blue   { background: #dbeafe; color: #1d4ed8; }
.rp-badge--violet { background: #ede9fe; color: #5b21b6; }
.rp-badge--green  { background: #d1fae5; color: #065f46; }

/* ═══════ PROSE ═══════ */
.rp-prose {
  font-size: 13.5px; color: #4b5563; line-height: 1.75;
  margin: 0; padding: 10px 14px;
  background: #fafafa;
  border-left: 3px solid #e0e7ff;
  border-radius: 0 8px 8px 0;
}

/* ═══════ SIDEBAR MINI ITEMS ═══════ */
.rp-applicant-mini {
  display: flex; gap: 10px; align-items: flex-start;
  padding-bottom: 12px; margin-bottom: 12px;
  border-bottom: 1px solid #f3f4f6;
}
.rp-applicant-mini__avatar {
  width: 42px; height: 42px; border-radius: 12px;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 800; color: #fff; flex-shrink: 0;
}
.rp-applicant-mini__info {
  display: flex; flex-direction: column; gap: 1px;
}
.rp-applicant-mini__info strong { font-size: 13px; color: #111827; }
.rp-applicant-mini__info span   { font-size: 11.5px; color: #9ca3af; }

.rp-mini-fields { display: flex; flex-direction: column; gap: 8px; }
.rp-mf { display: flex; justify-content: space-between; align-items: center; }
.rp-mf__l { font-size: 11px; font-weight: 600; color: #9ca3af; }
.rp-mf__v { font-size: 12.5px; color: #374151; font-weight: 500; }

.rp-latest-note { display: flex; gap: 10px; }
.rp-latest-note__avatar {
  width: 30px; height: 30px; border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex; align-items: center; justify-content: center;
  font-size: 11.5px; font-weight: 800; color: #fff; flex-shrink: 0;
}
.rp-latest-note__user { font-size: 12px; font-weight: 700; color: #374151; }
.rp-latest-note__time { font-size: 11px; color: #9ca3af; margin-bottom: 4px; }
.rp-latest-note__text { font-size: 12.5px; color: #6b7280; margin: 0; line-height: 1.5; }

/* ═══════ SCORE ═══════ */
.rp-score-circle {
  width: 80px; height: 80px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  flex-direction: column; margin: 0 auto 12px;
  border: 3px solid transparent;
}
.rp-score-circle--lg { width: 100px; height: 100px; margin-bottom: 16px; }
.rp-sc--green { background: #d1fae5; border-color: #10b981; }
.rp-sc--amber { background: #fef3c7; border-color: #f59e0b; }
.rp-sc--red   { background: #fee2e2; border-color: #ef4444; }
.rp-sc--empty { background: #f3f4f6; border-color: #e5e7eb; }
.rp-sc__num { font-size: 26px; font-weight: 900; color: #111827; line-height: 1; }
.rp-sc__den { font-size: 11px; color: #9ca3af; font-weight: 600; }

.rp-score-bar-wrap {
  height: 8px; background: #f3f4f6;
  border-radius: 999px; overflow: hidden; margin: 0 0 10px;
}
.rp-score-bar-wrap--lg { height: 10px; }
.rp-score-bar {
  height: 100%; border-radius: 999px;
  transition: width .6s cubic-bezier(.4,0,.2,1);
}
.rp-score-verdict {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 12px; border-radius: 999px;
  font-size: 12px; font-weight: 700; margin: 6px 0 14px;
}
.rp-score-instruction {
  font-size: 13px; color: #6b7280; margin: 0 0 14px;
}
.rp-score-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin-bottom: 16px;
}
.rp-sn {
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 10px 6px;
  border: 2px solid #e5e7eb; border-radius: 10px;
  background: #fff; cursor: pointer;
  transition: all .15s; font-family: inherit;
}
.rp-sn:hover { border-color: #a5b4fc; background: #f5f3ff; }
.rp-sn__num { font-size: 17px; font-weight: 800; color: #374151; }
.rp-sn__lbl { font-size: 9px; font-weight: 700; text-transform: uppercase; color: #9ca3af; letter-spacing: .4px; }
.rp-sn--sel { transform: scale(1.06); }
.rp-sn--low.rp-sn--sel  { background: #fee2e2; border-color: #ef4444; }
.rp-sn--low.rp-sn--sel .rp-sn__num { color: #dc2626; }
.rp-sn--mid.rp-sn--sel  { background: #fef3c7; border-color: #f59e0b; }
.rp-sn--mid.rp-sn--sel .rp-sn__num { color: #d97706; }
.rp-sn--high.rp-sn--sel { background: #d1fae5; border-color: #10b981; }
.rp-sn--high.rp-sn--sel .rp-sn__num { color: #059669; }

.rp-score-selected {
  font-size: 13.5px; font-weight: 700; margin-top: 4px;
  display: flex; justify-content: center;
}
.rp-score-locked { text-align: center; }
.rp-locked-note {
  font-size: 12px; color: #9ca3af;
  display: flex; align-items: center; justify-content: center;
  gap: 5px; margin: 8px 0 0;
}

/* ═══════ COMPOSE / STREAM ═══════ */
.rp-compose { margin-bottom: 16px; }
.rp-compose__header {
  display: flex; align-items: center; gap: 10px; margin-bottom: 10px;
}
.rp-compose__avatar {
  width: 32px; height: 32px; border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex; align-items: center; justify-content: center;
  font-size: 11.5px; font-weight: 800; color: #fff; flex-shrink: 0;
}
.rp-compose__label { font-size: 13px; color: #6b7280; font-weight: 500; }
.rp-textarea {
  width: 100%; padding: 10px 14px;
  border: 1.5px solid #e5e7eb; border-radius: 10px;
  font-size: 13.5px; color: #111827; resize: vertical;
  outline: none; font-family: inherit;
  transition: border-color .18s, box-shadow .18s;
}
.rp-textarea:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,.1);
}
.rp-compose__footer {
  display: flex; justify-content: space-between;
  align-items: center; margin-top: 8px;
}
.rp-char-count { font-size: 11.5px; color: #9ca3af; }

.rp-stream__divider {
  display: flex; align-items: center; gap: 10px;
  font-size: 11px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .5px; color: #9ca3af; margin-bottom: 14px;
}
.rp-stream__divider::before,
.rp-stream__divider::after {
  content: ''; flex: 1; height: 1px; background: #f0f1f3;
}
.rp-stream__item {
  display: flex; gap: 10px; margin-bottom: 12px;
}
.rp-stream__av {
  width: 30px; height: 30px; border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex; align-items: center; justify-content: center;
  font-size: 11.5px; font-weight: 800; color: #fff; flex-shrink: 0;
}
.rp-stream__body {
  flex: 1; background: #f9fafb;
  border-radius: 0 10px 10px 10px;
  padding: 9px 12px; border: 1px solid #f0f1f3;
}
.rp-stream__meta {
  display: flex; justify-content: space-between; margin-bottom: 4px;
}
.rp-stream__meta strong { font-size: 12.5px; color: #374151; }
.rp-stream__meta span   { font-size: 11.5px; color: #9ca3af; }
.rp-stream__text { font-size: 13px; color: #4b5563; margin: 0; line-height: 1.55; }

/* ═══════ DOCUMENTS ═══════ */
.rp-doc-list { display: flex; flex-direction: column; gap: 8px; }
.rp-doc {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border: 1px solid #e9eaec;
  border-radius: 10px; background: #fafafa;
  transition: border-color .15s, box-shadow .15s;
}
.rp-doc:hover { border-color: #a5b4fc; box-shadow: 0 2px 8px rgba(99,102,241,.08); }
.rp-doc__ico {
  width: 36px; height: 36px; border-radius: 8px;
  background: #e0e7ff; color: #4338ca;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; flex-shrink: 0;
}
.rp-doc__ico--violet { background: #ede9fe; color: #7c3aed; }
.rp-doc__info { flex: 1; overflow: hidden; }
.rp-doc__name {
  display: block; font-size: 13px; font-weight: 600; color: #111827;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.rp-doc__size { font-size: 11.5px; color: #9ca3af; }
.rp-doc__dl {
  flex-shrink: 0; background: #6366f1; color: #fff;
  padding: 6px 14px; border-radius: 8px; font-size: 12px;
  font-weight: 600; text-decoration: none;
  display: flex; align-items: center; gap: 5px;
  transition: background .15s;
}
.rp-doc__dl:hover { background: #4338ca; }
.rp-doc__dl--violet { background: #7c3aed; }
.rp-doc__dl--violet:hover { background: #5b21b6; }

/* Submit bar at bottom — also needs side padding */
.rp-submit-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 28px;
  background: #fff;
  border-radius: 0;
  border: none;
  border-top: 1px solid #e9eaec;
  margin-top: 16px; gap: 12px; flex-wrap: wrap;
}
.rp-submit-bar__left {
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; color: #6b7280; font-weight: 500;
}
.rp-submit-bar__left i { color: #6366f1; font-size: 15px; }

/* ═══════ EMPTY STATE ═══════ */
.rp-empty-state {
  text-align: center; padding: 24px 0; color: #9ca3af;
  display: flex; flex-direction: column;
  align-items: center; gap: 6px; font-size: 13px;
}
.rp-empty-state i { font-size: 26px; color: #d1d5db; }

/* ═══════ ALERT ═══════ */
.rp-alert {
  display: flex; align-items: center; gap: 9px;
  padding: 11px 14px; border-radius: 10px;
  font-size: 13.5px; margin-bottom: 14px;
}
.rp-alert--err { background: #fef2f2; border: 1px solid #fecaca; color: #991b1b; }

/* ═══════ BUTTONS ═══════ */
.rp-btn {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 9px 20px; border-radius: 10px;
  font-size: 13.5px; font-weight: 600; cursor: pointer;
  border: none; text-decoration: none; transition: all .18s;
  font-family: inherit;
}
.rp-btn--primary {
  background: linear-gradient(135deg, #6366f1, #4f46e5);
  color: #fff;
  box-shadow: 0 3px 10px rgba(99,102,241,.3);
}
.rp-btn--primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #4f46e5, #3730a3);
  box-shadow: 0 6px 18px rgba(99,102,241,.35);
  transform: translateY(-1px);
}
.rp-btn--primary:disabled { opacity: .5; cursor: not-allowed; box-shadow: none; transform: none; }
.rp-btn--ghost {
  background: #fff; color: #374151;
  border: 1.5px solid #e5e7eb;
}
.rp-btn--ghost:hover { border-color: #d1d5db; background: #f9fafb; }
.rp-btn--full  { width: 100%; justify-content: center; margin-top: 12px; }
.rp-btn--sm    { padding: 6px 14px; font-size: 12.5px; border-radius: 8px; }
.rp-btn--lg    { padding: 11px 28px; font-size: 14px; border-radius: 11px; }

/* Responsive side padding adjustment */
@media (max-width: 900px) {
  .rp-hero        { padding: 16px 16px 20px; }
  .rp-tabs        { padding: 5px 16px; }
  .rp-tab-panel   { padding: 0 16px; }
  .rp-banner      { padding: 10px 16px; }
  .rp-submit-bar  { padding: 16px 16px; }
  .rp-ov-grid       { grid-template-columns: 1fr; }
  .rp-twoCol        { grid-template-columns: 1fr; }
  .rp-review-layout { grid-template-columns: 1fr; }
  .rp-fields--3     { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 560px) {
  .rp-hero        { padding: 14px 12px 18px; }
  .rp-tabs        { padding: 5px 12px; }
  .rp-tab-panel   { padding: 0 12px; }
  .rp-fields--2,
  .rp-fields--3 { grid-template-columns: 1fr; }
  .rp-f--span2  { grid-column: span 1; }
  .rp-score-grid { grid-template-columns: repeat(5,1fr); gap: 5px; }
}
.rp-btn--reject {
  background: #dc2626;
  color: #fff;
  box-shadow: 0 3px 10px rgba(220,38,38,.25);
}
.rp-btn--reject:hover:not([disabled]) {
  background: #b91c1c;
  box-shadow: 0 6px 18px rgba(220,38,38,.35);
  transform: translateY(-1px);
}
.rp-btn--reject[disabled] {
  opacity: .5;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

sp_widget.script:
(function() {
    data.found = false;
    data.success = false;
    data.error = '';
    data.submitted = false;
    data.last_reviewer = false;
    data.is_last_reviewer = false;

    var userId = gs.getUserID();

    // ── GET CURRENT USER'S GROUPS ──
    var userGroups = [];
    var groupMemberGR = new GlideRecordSecure('sys_user_grmember');
    groupMemberGR.addQuery('user', userId);
    groupMemberGR.query();
    while (groupMemberGR.next()) {
        userGroups.push(groupMemberGR.getValue('group'));
    }

    var sysId = $sp.getParameter('sys_id');
    if (!sysId) return;

    var reviewRecordGR = new GlideRecordSecure('x_enno_gatenow_grant_review');
    if (!reviewRecordGR.get(sysId)) return;

    // ── ACCESS GUARD ──
    var isCurrentlyAssigned = userGroups.indexOf(reviewRecordGR.getValue('review_group')) !== -1;
    var reviewerRaw = reviewRecordGR.getValue('reviewer') || '';
    var isPartOfReview = false;

    for (var g = 0; g < userGroups.length; g++) {
        if (reviewerRaw.indexOf(userGroups[g]) !== -1) {
            isPartOfReview = true;
            break;
        }
    }

    if (!isCurrentlyAssigned && !isPartOfReview) return;

    // ── HANDLE ADD WORK NOTE ──
    if (input && input.action === 'add_note' && input.form) {
        if (input.form.comments) {
            reviewRecordGR.work_notes = input.form.comments;
            reviewRecordGR.update();
        }
        data.found = true;
        data.success = true;
    }

    // ── HANDLE REJECT ──
    if (input && input.action === 'reject_review') {
        var currentStatus = (reviewRecordGR.getValue('status') || '').toString().trim();

        if (currentStatus === 'Declined by Reviewer') {
            data.found = true;
            data.success = false;
            data.error = 'This review has already been declined.';
            return;
        }
        if (currentStatus === 'Review completed') {
            data.found = true;
            data.success = false;
            data.error = 'Cannot decline a completed review.';
            return;
        }

        reviewRecordGR.setValue('status', 'Declined by Reviewer');
        reviewRecordGR.update();
        data.found = true;
        data.success = true;
        return;
    }

    // ── HANDLE SUBMIT ──
    if (input && input.action === 'submit_review' && input.form) {
        var form = input.form;
        var groupListRaw = reviewRecordGR.getValue('reviewer') || '';
        var groupArray = groupListRaw.split(',').map(function(s) {
            return s.trim();
        }).filter(function(s) { return s !== ''; });

        var currentGroupSysId = reviewRecordGR.getValue('review_group');
        var currentIndex = groupArray.indexOf(currentGroupSysId);
        var nextIndex = currentIndex + 1;

        if (form.comments) reviewRecordGR.work_notes = form.comments;

        if (currentIndex === -1 || nextIndex >= groupArray.length) {
            // LAST GROUP
            if (form.score) reviewRecordGR.setValue('score', parseInt(form.score, 10));
            reviewRecordGR.setValue('status', 'Review completed');
            reviewRecordGR.update();

            data.found = true;
            data.success = true;
            data.submitted = true;
            data.last_reviewer = true;
        } else {
            // NOT LAST — pass to next group
            var nextGroupSysId = groupArray[nextIndex];
            var nextGroupName = '';
            var nextGroupLookupGR = new GlideRecordSecure('sys_user_group');
            if (nextGroupLookupGR.get(nextGroupSysId)) {
                nextGroupName = nextGroupLookupGR.getDisplayValue('name');
            }

            reviewRecordGR.setValue('review_group', nextGroupSysId);
            reviewRecordGR.setValue('status', 'Review in progress');
            reviewRecordGR.update();

            data.found = true;
            data.success = true;
            data.submitted = true;
            data.last_reviewer = false;
            data.next_group = nextGroupName;
        }
    }

    // ── CHECK STATUS ──
    var currentReviewGroup = reviewRecordGR.getValue('review_group');
    var currentReviewStatus = (reviewRecordGR.getValue('status') || '').toString().trim();

    if (currentReviewStatus === 'Review completed' || userGroups.indexOf(currentReviewGroup) === -1) {
        data.submitted = true;
    }

    // ── VISIBILITY CHECK ──
    var fullReviewerListRaw = reviewRecordGR.getValue('reviewer') || '';
    var fullReviewerArray = fullReviewerListRaw.split(',').map(function(s) {
        return s.trim();
    }).filter(function(s) { return s !== ''; });

    var lastGroupInList = fullReviewerArray.length > 0 ? fullReviewerArray[fullReviewerArray.length - 1] : '';
    data.is_last_reviewer = (reviewRecordGR.getValue('review_group') === lastGroupInList) && 
                            (userGroups.indexOf(reviewRecordGR.getValue('review_group')) !== -1);

    // ── LOAD APPLICANT INFO ──
    var applicantId = reviewRecordGR.getValue('applicant');
    var applicantData = {};
    if (applicantId) {
        var applicantGR = new GlideRecordSecure('x_enno_gatenow_service_applicants');
        if (applicantGR.get(applicantId)) {
            applicantData.number = applicantGR.getValue('number') || '';
            applicantData.first_name = applicantGR.getValue('first_name') || '';
            applicantData.middle_name = applicantGR.getValue('middle_name') || '';
            applicantData.last_name = applicantGR.getValue('last_name') || '';
            applicantData.email = applicantGR.getValue('email') || '';
            applicantData.phone = applicantGR.getValue('phone_number') || '';
            applicantData.gender = applicantGR.getDisplayValue('gender') || '';
            applicantData.dob = applicantGR.getDisplayValue('birthdate') || '';
            applicantData.marital_status = applicantGR.getDisplayValue('marital_status') || '';
            applicantData.race = applicantGR.getDisplayValue('race') || '';
            applicantData.ethnicity = applicantGR.getDisplayValue('ethnicity') || '';
            applicantData.education = applicantGR.getDisplayValue('education_level') || '';
            applicantData.military_status = applicantGR.getDisplayValue('military_status') || '';
            applicantData.applicant_type = applicantGR.getDisplayValue('applicant_type') || '';
            applicantData.tribal = applicantGR.getDisplayValue('tribal_affiliation') || '';
            applicantData.citizenship = applicantGR.getDisplayValue('citizenship_status') || '';
            applicantData.identity_type = applicantGR.getDisplayValue('identity_type') || '';
            applicantData.disability = applicantGR.getDisplayValue('disability_status') || '';
            applicantData.ssn = applicantGR.getValue('ssn') || '';
            applicantData.tin = applicantGR.getValue('tin_ein') || '';
            applicantData.uei = applicantGR.getValue('uei') || '';
            applicantData.street = applicantGR.getValue('street') || '';
            applicantData.city = applicantGR.getValue('city') || '';
            applicantData.country = applicantGR.getValue('country') || '';
            applicantData.zip = applicantGR.getValue('zip_postal_code') || '';
            applicantData.organization = applicantGR.getValue('organization') || '';
            applicantData.program_category = applicantGR.getDisplayValue('program_category') || '';
            applicantData.requested_budget = applicantGR.getDisplayValue('requested_budget') || '';
            applicantData.short_desc = applicantGR.getValue('short_description') || '';
            applicantData.proposal_desc = applicantGR.getValue('proposal_description') || '';
            applicantData.goals = applicantGR.getValue('project_goals_and_objectives') || '';
            applicantData.methodology = applicantGR.getValue('project_activities_methodology') || '';
            applicantData.project_start = applicantGR.getDisplayValue('project_start_date') || '';
            applicantData.project_end = applicantGR.getDisplayValue('project_end_date') || '';
            applicantData.submission_date = applicantGR.getDisplayValue('submission_date') || '';
            applicantData.state = applicantGR.getDisplayValue('state') || '';

            var appDocs = [];
            var appAttachmentGR = new GlideRecordSecure('sys_attachment');
            appAttachmentGR.addQuery('table_name', 'x_enno_gatenow_service_applicants');
            appAttachmentGR.addQuery('table_sys_id', applicantGR.getUniqueValue());
            appAttachmentGR.query();
            while (appAttachmentGR.next()) {
                appDocs.push({
                    name: appAttachmentGR.getValue('file_name'),
                    size: appAttachmentGR.getValue('size_bytes'),
                    sys_id: appAttachmentGR.getValue('sys_id'),
                    url: '/sys_attachment.do?sys_id=' + appAttachmentGR.getValue('sys_id')
                });
            }
            applicantData.documents = appDocs;
        }
    }

    // ── LOAD PROGRAM INFO ──
    var programId = reviewRecordGR.getValue('program');
    var programData = {};
    if (programId) {
        var programGR = new GlideRecordSecure('x_enno_gatenow_grant_program');
        if (programGR.get(programId)) {
            programData.name = programGR.getDisplayValue('program_name') || '';
            programData.number = programGR.getValue('number') || '';
            programData.start_date = programGR.getDisplayValue('start_date') || '';
            programData.category = programGR.getDisplayValue('category') || '';
            programData.end_date = programGR.getDisplayValue('end_date') || '';
            programData.status = programGR.getDisplayValue('status') || '';
            programData.budget = programGR.getDisplayValue('program_budget') || '';
            programData.description = programGR.getValue('program_description') || '';
            programData.synopsis = programGR.getValue('synopsis') || '';
            programData.terms = programGR.getValue('terms_and_conditions') || '';
            programData.eligibility = programGR.getValue('eligibility_summary') || '';
            programData.summary_statement = programGR.getValue('summary_statement') || '';

            var progDocs = [];
            var progAttachmentGR = new GlideRecordSecure('sys_attachment');
            progAttachmentGR.addQuery('table_name', 'x_enno_gatenow_grant_program');
            progAttachmentGR.addQuery('table_sys_id', programGR.getUniqueValue());
            progAttachmentGR.query();
            while (progAttachmentGR.next()) {
                progDocs.push({
                    name: progAttachmentGR.getValue('file_name'),
                    size: progAttachmentGR.getValue('size_bytes'),
                    sys_id: progAttachmentGR.getValue('sys_id'),
                    url: '/sys_attachment.do?sys_id=' + progAttachmentGR.getValue('sys_id')
                });
            }
            programData.documents = progDocs;
        }
    }

    // ── LOAD WORK NOTES (Journal) ──
    var workNotesHistory = [];
    var journalGR = new GlideRecordSecure('sys_journal_field');
    journalGR.addQuery('name', 'x_enno_gatenow_grant_review');
    journalGR.addQuery('element', 'work_notes');
    journalGR.addQuery('element_id', reviewRecordGR.getUniqueValue());
    journalGR.orderByDesc('sys_created_on');
    journalGR.query();
    while (journalGR.next()) {
        workNotesHistory.push({
            value: journalGR.getValue('value'),
            created: journalGR.getDisplayValue('sys_created_on'),
            user: journalGR.getDisplayValue('sys_created_by')
        });
    }

    // ── FINAL DATA ASSIGNMENT ──
    data.found = true;
    data.sys_id = reviewRecordGR.getUniqueValue();
    data.number = reviewRecordGR.getValue('number');
    data.review_group = reviewRecordGR.getDisplayValue('review_group');
    data.status = reviewRecordGR.getDisplayValue('status');
    data.score = reviewRecordGR.getValue('score');
    data.work_notes = reviewRecordGR.getValue('work_notes') || '';
    data.work_notes_list = workNotesHistory;
    data.applicant = applicantData;
    data.program = programData;
})();
